import{_ as t}from"./chunks/synth_pocket.DKHPe-i5.js";import{_ as s,o as a,c as i,a2 as o}from"./chunks/framework.hw3Av5Vn.js";const m=JSON.parse('{"title":"Pocket","description":"","frontmatter":{},"headers":[],"relativePath":"synths/engines/POCKET.md","filePath":"synths/engines/POCKET.md"}'),r={name:"synths/engines/POCKET.md"};function n(h,e,p,c,l,d){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="pocket" tabindex="-1">Pocket <a class="header-anchor" href="#pocket" aria-label="Permalink to &quot;Pocket&quot;">​</a></h1><p>Pocket is one voice of a small 4-bit sound chip: a Pulse of one of four duties, a drawn Wave of a few dozen 4-bit steps in one of five shapes, or Noise, long or short, with a pitch sweep and the chip&#39;s stepped <a href="./../ENVELOPES#chip-steps">Chip steps</a> envelope. It is the sound of small, bright chip melodies and their chirps and zaps. Detune moves the voice by cents and Fine by tenths of a cent, for beating against another track.</p><p><img src="'+t+'" alt="The Oscillators tab of Pocket"></p><h2 id="how-pocket-is-built" tabindex="-1">How Pocket Is Built <a class="header-anchor" href="#how-pocket-is-built" aria-label="Permalink to &quot;How Pocket Is Built&quot;">​</a></h2><p>The chip doesn&#39;t play a frequency; it counts down a period register from a fixed clock, and a note&#39;s pitch is the nearest register value, so that its tuning is the chip&#39;s own slightly crooked one. Each pulse duty and each drawn wave is a single cycle made into band-limited tables: its harmonics measured by one Fourier transform, then each octave&#39;s table keeping those under half the sample rate. So a stepped wave keeps its steps right up to where they would alias, and no further.</p><p>The noise is a shift register: its two lowest bits are combined by exclusive or and fed back in at the top as it shifts, and each shift gives the next value, high or low. Long noise uses the whole register, a hiss that hardly repeats; short noise uses a short part of it, so it repeats quickly as a metallic buzz.</p><p>The sweep moves the period register itself, as the chip does: at each tick of its Sweep pace, the register is shifted right by its Sweep step and that amount added or taken away, so that the pitch slides by a share of itself, quickly at first. A sweep up that runs past the register&#39;s top silences the voice, as on the chip.</p>',7)])])}const g=s(r,[["render",n]]);export{m as __pageData,g as default};
